<script>/* ============================================================================
   Padcolor Pre-Pedidos v7 - Aplicación principal
   ============================================================================ */
(function(){
'use strict';

// ===== Carga de datos =====
const DATA = JSON.parse(document.getElementById('DATA_JSON').textContent);
const PRODUCTS = DATA.products;
// Orden estable global: por página del catálogo ASC, luego por código UPC.
// Productos sin página quedan al final.
PRODUCTS.sort((a, b) => {
  const pa = a.p || 99999;
  const pb = b.p || 99999;
  if (pa !== pb) return pa - pb;
  return (a.c || '').localeCompare(b.c || '');
});
const CLIENTS = DATA.clients;
const AGENTS = DATA.agents;
const CATEGORIES = DATA.categories;
const GRUPOS = DATA.grupos;

// Imágenes del catálogo (página impresa → dataURL JPEG base64).
// El elemento puede no existir si el HTML se sirvió sin imágenes.
const IMAGES = (function(){
  const el = document.getElementById('IMAGES_JSON');
  if(!el) return {};
  try { return JSON.parse(el.textContent); }
  catch(e){ console.warn('IMAGES_JSON parse failed', e); return {}; }
})();

// ===== Mapas de búsqueda rápida =====
const CLIENTS_BY_NUM = {};
CLIENTS.forEach(c => CLIENTS_BY_NUM[c.n.toUpperCase()] = c);
const AGENTS_BY_NAME = {};
AGENTS.forEach(a => AGENTS_BY_NAME[a.nom.toUpperCase()] = a);

// Mapa entidad -> almacenes (para referencia, ya viene calculado por entidad)
const PRICE_LIST_INDEX = {'LISTA':0,'A':1,'B':2,'C':3};

// ===== Estado global =====
const state = {
  cliente: null,           // objeto cliente o sentinel { x: 'COMODIN' } para XXXXX
  agente: null,            // objeto agente
  entidad: 'TGR',          // C2 o TGR según el agente
  priceIdx: 0,             // 0=Lista, 1=A, 2=B, 3=C
  carrito: {},             // {codigo: {p: <product>, q: <paquetes>}}
  search: '',
  filterEspecial: false,
  filterNuevos: false,
  filterGrupo: '',
  filterPage: '',
  showLimit: 60,           // virtualización ligera: solo render N a la vez
};

// ===== Helpers =====
const $ = (id) => document.getElementById(id);
const fmt = (n) => '$' + (Number(n)||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtInt = (n) => (Number(n)||0).toLocaleString('es-MX');

function toast(msg, type='info', ms=3000){
  const t = document.createElement('div');
  t.className = 'toast' + (type==='success'?' success':type==='error'?' error':'');
  t.textContent = msg;
  $('toast-area').appendChild(t);
  setTimeout(()=>t.remove(), ms);
}

function showModal(title, bodyHTML, footerHTML, opts){
  opts = opts || {};
  $('modal-title').textContent = title;
  $('modal-body').innerHTML = bodyHTML;
  const mc = $('modal-content');
  mc.classList.toggle('modal-wide', !!opts.wide);
  if(footerHTML === null){
    $('modal-footer').style.display = 'none';
  } else {
    $('modal-footer').style.display = '';
    if(footerHTML !== undefined){
      $('modal-footer').innerHTML = footerHTML;
    } else {
      $('modal-footer').innerHTML = '<button class="filter-toggle" data-close>Cerrar</button>';
    }
  }
  $('modal').classList.add('show');
}
function closeModal(){ $('modal').classList.remove('show'); }
$('modal').addEventListener('click', e => {
  if(e.target.id==='modal' || e.target.dataset.close !== undefined) closeModal();
});

// ===== Cliente: validación =====
function validarCliente(num){
  const upper = (num||'').trim().toUpperCase();
  if(!upper){ state.cliente = null; resetClienteUI(); renderProductos(); return; }

  // Cliente comodín
  if(upper === 'XXXXX'){
    state.cliente = { _comodin: true, n: 'XXXXX', rs:'', nc:'', rfc:'', lc:0, sa:0, pl:'Lista', plz:30, dom:'' };
    state.priceIdx = 0;
    state.entidad = 'TGR';
    state.agente = { nom:'Asistente de Ventas', mail:'auxventas@padcolor.com', wa:'', ent:'TGR' };
    aplicarClienteUI();
    setMsg('cli-msg', 'Cliente comodín XXXXX activo. Lista de precios: Lista. Sin crédito. El pedido irá al asistente de ventas. Captura RFC para continuar.', 'success');
    $('cli-num').classList.add('success');
    $('cli-num').classList.remove('error');
    bloquearForm(false);
    actualizarFinalizar();
    renderProductos();
    return;
  }

  const cli = CLIENTS_BY_NUM[upper];
  if(!cli){
    state.cliente = null;
    state.agente = null;
    setMsg('cli-msg', 'No existe. Intentar de nuevo.', 'error');
    $('cli-num').classList.add('error');
    $('cli-num').classList.remove('success');
    resetClienteUI();
    bloquearForm(true);
    renderProductos();
    return;
  }
  if(cli.bl === 'Checked'){
    state.cliente = null;
    state.agente = null;
    setMsg('cli-msg', 'Cliente con bloqueo administrativo. Contacta a tu ejecutivo.', 'error');
    $('cli-num').classList.add('error');
    $('cli-num').classList.remove('success');
    resetClienteUI();
    bloquearForm(true);
    renderProductos();
    return;
  }
  // Cliente OK
  state.cliente = cli;
  const plKey = (cli.pl||'Lista').toUpperCase();
  state.priceIdx = PRICE_LIST_INDEX[plKey] !== undefined ? PRICE_LIST_INDEX[plKey] : 0;
  state.agente = AGENTS_BY_NAME[(cli.ag||'').toUpperCase()] || null;
  state.entidad = state.agente ? state.agente.ent : 'TGR';

  aplicarClienteUI();
  setMsg('cli-msg', '', '');
  $('cli-num').classList.add('success');
  $('cli-num').classList.remove('error');
  bloquearForm(false);
  actualizarFinalizar();
  renderProductos();
}

// ===== Helpers de formato =====
function formatWhatsApp(raw){
  // Acepta cualquier formato, extrae dígitos y formatea como (XX)XXXX-XXXX
  if(!raw) return '';
  const d = String(raw).replace(/\D/g,'');
  if(d.length === 10) return `(${d.slice(0,2)})${d.slice(2,6)}-${d.slice(6,10)}`;
  return raw; // si no son 10 dígitos, devolver como vino
}
function setMsg(id, msg, type){
  const el = $(id);
  el.textContent = msg;
  el.className = 'form-msg' + (msg ? ' show ' + (type||'') : '');
}
function resetClienteUI(){
  $('cli-nc').value = '';
  $('cli-rfc').value = '';
  // cli-lc / cli-disp viven dentro del bloque amarillo de exceso de crédito,
  // que se llena y muestra solo cuando el total del pedido excede el límite.
  $('ag-nombre').textContent = 'Captura tu núm. de cliente';
  $('ag-nombre').classList.add('ag-empty');
  $('ag-wa').textContent = '—';
  $('ag-wa').classList.add('ag-empty');
  $('ag-mail').textContent = '—';
  $('ag-mail').classList.add('ag-empty');
  // Expandir identity-card si estaba colapsado (cliente borrado/inválido)
  const card = document.getElementById('identity-card');
  if(card) card.classList.remove('compact');
}
function aplicarClienteUI(){
  const cli = state.cliente;
  $('cli-nc').value = cli.nc || cli.rs || '';
  // NO auto-completar el RFC: el cliente DEBE capturarlo y debe coincidir
  // con el del catálogo (validación de seguridad).
  $('cli-rfc').value = '';
  validarRfc();
  // cli-lc / cli-disp se actualizan en renderCarrito sólo cuando el bloque
  // amarillo de exceso de crédito está visible. No se llenan acá.
  if(state.agente){
    $('ag-nombre').textContent = state.agente.nom;
    $('ag-nombre').classList.remove('ag-empty');
    const waFmt = formatWhatsApp(state.agente.wa);
    $('ag-wa').textContent = waFmt || '—';
    $('ag-wa').classList.toggle('ag-empty', !waFmt);
    $('ag-mail').textContent = state.agente.mail || '—';
    $('ag-mail').classList.toggle('ag-empty', !state.agente.mail);
  }
}
function bloquearForm(bloq){
  ['cli-email','cli-tel','cli-rfc'].forEach(id => $(id).disabled = bloq);
  $('btn-finalize').disabled = bloq;
}

// ===== Inventario por entidad del cliente =====
function getStock(prod){
  if(!state.cliente) return prod.qC + prod.qT; // antes de validar, suma de ambas
  return state.entidad === 'C2' ? prod.qC : prod.qT;
}
function getStockPiezas(prod){
  if(!state.cliente) return prod.iC + prod.iT;
  return state.entidad === 'C2' ? prod.iC : prod.iT;
}

// ===== Precios =====
function getPrecioPieza(prod){
  return prod.pp[state.priceIdx] || 0;
}
function getPrecioPaquete(prod){
  // Si trae el precio múltiplo lo usa; si no, calcula precio_pieza × multiplo
  const pq = prod.pq[state.priceIdx];
  if(pq && pq > 0) return pq;
  return getPrecioPieza(prod) * prod.m;
}
function tienePrecio(prod){
  return getPrecioPieza(prod) > 0 || getPrecioPaquete(prod) > 0;
}

// ===== Filtrado =====
let _filteredCache = null;
function filterProducts(){
  const q = state.search.trim().toLowerCase();
  const qDigits = q.replace(/\D/g,'');
  const onlyEsp = state.filterEspecial;
  const onlyNuevos = state.filterNuevos;
  const grp = state.filterGrupo;
  const pag = state.filterPage;

  const result = PRODUCTS.filter(p => {
    if(onlyEsp && !p.e) return false;
    if(onlyNuevos && !p.n) return false;
    if(grp && p.g !== grp) return false;
    if(pag && String(p.p||'') !== pag) return false;
    if(q){
      const hay = (p.d||'').toLowerCase();
      const cod = (p.c||'').toLowerCase();
      const cp = (p.cp||'').toLowerCase();
      const u5 = (p.u5||'').toLowerCase();
      const sr = (p.sr||'').toLowerCase();
      const tm = (p.tm||'').toLowerCase();
      const cat = (p.cat||'').toLowerCase();
      // Match: cualquier término de búsqueda en cualquier campo
      const terms = q.split(/\s+/).filter(Boolean);
      for(const t of terms){
        const tDigits = t.replace(/\D/g,'');
        const inText = hay.includes(t) || cat.includes(t) || sr.includes(t) || tm.includes(t);
        const inCode = (cod.includes(t) || (tDigits && (cod.includes(tDigits) || cp.includes(tDigits) || u5.includes(tDigits))));
        if(!inText && !inCode) return false;
      }
    }
    return true;
  });
  _filteredCache = result;
  return result;
}

// ===== Render productos =====
// ===== Helper: cliente listo para mostrar catálogo =====
// El catálogo (productos + precios) y el carrito sólo se habilitan cuando:
// (a) hay un cliente validado, y
// (b) el RFC capturado pasa la validación (formato + coincidencia con catálogo).
function clienteListo(){
  if(!state.cliente) return false;
  const v = ($('cli-rfc').value || '').toUpperCase().trim();
  const formatoOk = /^[A-ZÑ&]{3,4}\d{6}[A-Z\d]{3}$/.test(v);
  if(!formatoOk) return false;
  if(state.cliente._comodin) return true;
  const rfcCat = (state.cliente.rfc || '').toUpperCase().trim();
  // Si el cliente no tiene RFC registrado, aceptar cualquier RFC con formato válido
  if(!rfcCat) return true;
  return v === rfcCat;
}

function renderProductos(){
  // Actualizar banner de lista de precios
  const banner = $('price-list-banner');
  const bannerText = $('price-list-banner-text');
  if(banner && bannerText){
    const listas = ['Lista', 'A', 'B', 'C'];
    const listaActual = listas[state.priceIdx] || 'Lista';
    if(clienteListo()){
      const cliNum = state.cliente._comodin ? 'XXXXX' : state.cliente.n;
      bannerText.innerHTML = `Mostrando precios <strong>${listaActual}</strong> para cliente <strong>${cliNum}</strong>.`;
      banner.classList.add('ready');
    } else {
      bannerText.innerHTML = `<span class="banner-text-desktop">Mostrando precios <strong>Lista</strong>. Captura tu número de cliente y RFC para ver tus precios y habilitar el carrito.</span><span class="banner-text-mobile">Identifícate arriba ↑ para ver tus precios y habilitar el carrito.</span>`;
      banner.classList.remove('ready');
    }
  }

  const filtered = filterProducts();
  const total = PRODUCTS.length;
  $('count-shown').textContent = filtered.length;
  $('count-total').textContent = total;

  // Mostrar/ocultar reset
  const anyFilter = state.search || state.filterEspecial || state.filterNuevos ||
                    state.filterGrupo || state.filterPage;
  $('reset-filters').style.display = anyFilter ? 'inline-flex' : 'none';

  const grid = $('products-grid');
  const empty = $('empty-state');
  const loadMore = $('load-more');

  if(filtered.length === 0){
    grid.innerHTML = '';
    empty.innerHTML = 'No se encontraron productos con los filtros actuales.';
    empty.style.display = 'block';
    loadMore.style.display = 'none';
    return;
  }
  empty.style.display = 'none';

  // Render hasta showLimit
  const visible = filtered.slice(0, state.showLimit);
  grid.innerHTML = visible.map(p => productCardHTML(p)).join('');
  
  loadMore.style.display = filtered.length > state.showLimit ? 'block' : 'none';

  // Wire-up event listeners en cards
  grid.querySelectorAll('[data-add]').forEach(b => {
    b.addEventListener('click', () => addAlCarrito(b.dataset.add));
  });
  grid.querySelectorAll('[data-qmin]').forEach(b => {
    b.addEventListener('click', () => adjustQty(b.dataset.qmin, -1));
  });
  grid.querySelectorAll('[data-qplus]').forEach(b => {
    b.addEventListener('click', () => adjustQty(b.dataset.qplus, +1));
  });
  grid.querySelectorAll('[data-qty]').forEach(inp => {
    inp.addEventListener('input', e => onQtyInput(inp.dataset.qty, e.target));
    inp.addEventListener('blur', e => clampQty(inp.dataset.qty, e.target));
  });
  grid.querySelectorAll('[data-modelo]').forEach(b => {
    b.addEventListener('click', () => abrirModeloDetalle(b.dataset.modelo));
  });
}

function productCardHTML(p){
  const stock = getStock(p);
  const stockPz = getStockPiezas(p);
  const agotado = stock <= 0;
  const precioPz = getPrecioPieza(p);
  const precioPq = getPrecioPaquete(p);
  const sinPrecio = !tienePrecio(p);
  const inCart = state.carrito[p.c];
  const qty = inCart ? inCart.q : 0;
  const max = stock;

  // Imagen / placeholder
  let imgHTML = '';
  if(p.p){
    const src = IMAGES[p.p];
    if(src){
      imgHTML = `<div class="product-img has-img" data-page="${p.p}" data-modelo="${p.c}" title="Click para ampliar página ${p.p} del catálogo">
        <img src="${src}" alt="Página ${p.p}" loading="lazy">
        <span class="product-img-page">Pág ${p.p}</span>`;
    } else {
      imgHTML = `<div class="product-img" data-modelo="${p.c}" title="Página ${p.p} del catálogo">
        <span style="font-size:11px;color:var(--pad-grey-500);font-weight:600">📄 Página ${p.p}</span>
        <span class="product-img-page">Pág ${p.p}</span>`;
    }
    if(p.cp && p.pe){
      imgHTML += `<span class="product-img-modelo" title="Modelo en el PDF">#${p.cp}</span>`;
    }
    if(p.e) imgHTML += `<span class="product-tag-e">$E</span>`;
    if(p.n) imgHTML += `<span class="product-tag-nuevo">¡Nuevo!</span>`;
    imgHTML += `</div>`;
  } else {
    imgHTML = `<div class="product-img no-img">
      <span>Imagen no disponible</span>`;
    if(p.cp && p.pe){
      imgHTML += `<span class="product-img-modelo">#${p.cp}</span>`;
    }
    if(p.e) imgHTML += `<span class="product-tag-e">$E</span>`;
    if(p.n) imgHTML += `<span class="product-tag-nuevo">¡Nuevo!</span>`;
    imgHTML += `</div>`;
  }

  // Precios
  let priceHTML;
  if(sinPrecio){
    priceHTML = `<div class="price-noprice">Producto sin precio</div>`;
  } else {
    priceHTML = `
      <div class="price-block">
        <span class="price-label">Pieza</span>
        <span class="price-value">${fmt(precioPz)}</span>
      </div>
      <div class="price-block" style="text-align:right">
        <span class="price-label">Paquete</span>
        <span class="price-value price-paq">${fmt(precioPq)}</span>
      </div>`;
  }

  // Acciones
  const listo = clienteListo();
  const dis = agotado ? 'disabled' : '';
  const minDis = (qty<=0) ? 'disabled' : '';
  const plusDis = (qty>=max) ? 'disabled' : '';
  const addDis = (agotado || !listo) ? 'disabled' : '';
  const addTip = !listo ? 'title="Captura núm. de cliente y RFC para agregar al carrito"' : '';
  const addText = !listo ? '🔒 Agregar' : 'Agregar';
  const actionsHTML = agotado ? '' : `
    <div class="qty-label" style="margin-top:6px">Paquetes</div>
    <div class="product-actions">
      <div class="qty-input-wrap">
        <button class="qty-btn" data-qmin="${p.c}" ${minDis}>−</button>
        <input class="qty-input" type="number" min="0" max="${max}" value="${qty}" data-qty="${p.c}">
        <button class="qty-btn" data-qplus="${p.c}" ${plusDis}>+</button>
      </div>
      <button class="btn-add" data-add="${p.c}" ${addDis} ${addTip}>${addText}</button>
    </div>
    <div class="qty-max-hint">Máx: ${fmtInt(max)} paquetes (${fmtInt(stockPz)} pz)</div>`;

  // Stock label
  const stockClass = agotado ? 'out' : 'in';
  const stockText = agotado ? 'Agotado' : `${fmtInt(stock)} paquetes disponibles`;

  return `<div class="product-card${agotado?' agotado':''}">
    ${imgHTML}
    <div class="product-body">
      <span class="product-code">${p.c}${p.cp&&p.pe?' · #'+p.cp:''}</span>
      <span class="product-desc" title="${p.d.replace(/"/g,'&quot;')}">${p.d}</span>
      <span class="product-pack">📦 Unidad de venta: paq c/${p.m} pz</span>
      <span class="product-stock ${stockClass}">
        ${agotado?'⊘':'✓'} ${stockText}
      </span>
      <div class="product-prices">
        ${priceHTML}
      </div>
      ${actionsHTML}
    </div>
  </div>`;
}

function abrirModeloDetalle(codigo){
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p || !p.p) return;
  const src = IMAGES[p.p];
  const imgBlock = src
    ? `<div style="text-align:center;margin-bottom:14px">
         <img src="${src}" alt="Página ${p.p}" style="max-width:100%;max-height:70vh;border-radius:8px;box-shadow:0 4px 20px rgba(0,0,0,.15)">
       </div>`
    : `<div style="background:var(--pad-grey-100);padding:80px 20px;border-radius:8px;margin-bottom:14px;text-align:center">
         <div style="font-size:48px;color:var(--pad-grey-300)">📄</div>
         <div style="font-size:14px;color:var(--pad-grey-500);margin-top:10px">Imagen de la página ${p.p} del catálogo (no disponible)</div>
       </div>`;
  const body = `
    ${imgBlock}
    <h3 style="margin-bottom:8px">${p.d}</h3>
    <div style="font-size:12.5px;color:var(--pad-grey-700);line-height:1.7">
      <strong>Código UPC-A:</strong> ${p.c}<br>
      ${p.cp ? `<strong>Modelo (código en PDF):</strong> ${p.cp}<br>` : ''}
      ${p.u5 ? `<strong>Código central UPC (5 dígitos):</strong> ${p.u5}<br>` : ''}
      <strong>Página catálogo:</strong> ${p.p}<br>
      <strong>Categoría:</strong> ${p.cat}<br>
      ${p.sr ? `<strong>Serie:</strong> ${p.sr} · <strong>Tamaño:</strong> ${p.tm||'—'}<br>`:''}
    </div>`;
  showModal(`Producto del catálogo Verano 2026`, body);
}

// ===== Carrito =====
function addAlCarrito(codigo){
  if(!clienteListo()){ toast('Captura cliente y RFC para hacer pedido', 'error'); return; }
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p) return;
  const inputEl = document.querySelector(`[data-qty="${codigo}"]`);
  let qty = parseInt(inputEl?.value || '0', 10) || 0;
  if(qty <= 0) qty = 1;
  const max = getStock(p);
  if(qty > max) qty = max;
  if(qty <= 0){ toast('Sin existencia', 'error'); return; }

  state.carrito[codigo] = { p, q: qty };
  toast(`✓ Agregado: ${qty} paq de ${p.d.substring(0,40)}`, 'success', 1800);
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}
function adjustQty(codigo, delta){
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p) return;
  const inputEl = document.querySelector(`[data-qty="${codigo}"]`);
  if(!inputEl) return;
  let v = parseInt(inputEl.value || '0', 10) || 0;
  v += delta;
  const max = getStock(p);
  if(v < 0) v = 0;
  if(v > max) v = max;
  inputEl.value = v;
  // Actualizar estado de botones
  const minBtn = document.querySelector(`[data-qmin="${codigo}"]`);
  const plusBtn = document.querySelector(`[data-qplus="${codigo}"]`);
  if(minBtn) minBtn.disabled = v <= 0;
  if(plusBtn) plusBtn.disabled = v >= max;
}
function onQtyInput(codigo, input){
  const p = PRODUCTS.find(x => x.c === codigo);
  if(!p) return;
  let v = parseInt(input.value||'0',10);
  if(isNaN(v) || v < 0) v = 0;
  const max = getStock(p);
  if(v > max){ v = max; toast(`Máx ${max} paquetes disponibles`, 'error', 1500); }
  input.value = v;
}
function clampQty(codigo, input){
  let v = parseInt(input.value||'0',10);
  if(isNaN(v) || v < 0) input.value = 0;
}
function eliminarDelCarrito(codigo){
  delete state.carrito[codigo];
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}
function cambiarQtyCarrito(codigo, qty){
  const it = state.carrito[codigo];
  if(!it) return;
  const max = getStock(it.p);
  let v = parseInt(qty,10) || 0;
  if(v <= 0){ eliminarDelCarrito(codigo); return; }
  if(v > max) v = max;
  it.q = v;
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}

function renderCarrito(){
  const items = Object.values(state.carrito);
  $('cart-count').textContent = items.length === 0 ? '0 productos' :
    `${items.length} ${items.length===1?'producto':'productos'}`;
  
  const list = $('cart-list');
  if(items.length === 0){
    list.innerHTML = '<div class="cart-empty">El carrito está vacío.<br>Agrega productos del catálogo →</div>';
  } else {
    list.innerHTML = items.map(it => {
      const p = it.p;
      const sin = !tienePrecio(p);
      const precioPq = getPrecioPaquete(p);
      const subtotal = sin ? 0 : (it.q * precioPq * 1.16);
      const subHTML = sin
        ? `<div class="cart-item-sub noprice">Producto sin precio</div>`
        : `<div class="cart-item-sub">${fmt(subtotal)}</div>`;
      return `<div class="cart-item">
        <div class="cart-item-info">
          <div class="cart-item-desc">${p.d}</div>
          <div class="cart-item-meta">${p.c} · paq c/${p.m} pz · ${p.g}</div>
          <div class="cart-item-qty">
            <div class="qty-input-wrap">
              <button class="qty-btn" onclick="window.__padcolor.cartQty('${p.c}', ${it.q-1})">−</button>
              <input class="qty-input" type="number" min="0" value="${it.q}" 
                     onchange="window.__padcolor.cartQty('${p.c}', this.value)">
              <button class="qty-btn" onclick="window.__padcolor.cartQty('${p.c}', ${it.q+1})">+</button>
            </div>
          </div>
        </div>
        <div class="cart-item-price">
          ${sin ? '<div class="cart-item-unit">—</div>' : 
            `<div class="cart-item-unit">${fmt(precioPq)}/paq</div>`}
          ${subHTML}
        </div>
        <button class="cart-item-remove" onclick="window.__padcolor.cartRemove('${p.c}')" title="Eliminar">×</button>
      </div>`;
    }).join('');
  }
  
  // Total
  const total = items.reduce((s, it) => {
    if(!tienePrecio(it.p)) return s;
    return s + it.q * getPrecioPaquete(it.p) * 1.16;
  }, 0);
  $('total-value').textContent = fmt(total);
  
  // Aviso de pedido mínimo
  const minOk = total >= PEDIDO_MIN;
  const minNotice = $('cart-min-notice');
  if(minNotice){
    if(minOk){
      minNotice.textContent = `✓ Pedido mínimo cumplido (${fmt(PEDIDO_MIN)})`;
      minNotice.classList.add('satisfied');
    } else {
      const falta = PEDIDO_MIN - total;
      minNotice.textContent = items.length === 0
        ? `Pedido mínimo ${fmt(PEDIDO_MIN)}`
        : `Pedido mínimo ${fmt(PEDIDO_MIN)} · faltan ${fmt(falta)}`;
      minNotice.classList.remove('satisfied');
    }
  }
  
  // Color del total + bloque "excede tu crédito" (cifras + CTA aumento)
  const box = $('total-box');
  box.classList.remove('green','yellow');
  const exceedBox = $('credit-exceed-box');
  const wasShown = exceedBox.style.display !== 'none' && exceedBox.style.display !== '';
  if(state.cliente && !state.cliente._comodin && items.length > 0){
    const lc = state.cliente.lc || 0;
    const disp = Math.max(0, lc - (state.cliente.sa||0));
    if(total <= disp){
      box.classList.add('green');
      $('total-msg').textContent = '';
      exceedBox.style.display = 'none';
    } else {
      box.classList.add('yellow');
      $('total-msg').textContent = `Excede tu crédito disponible por ${fmt(total-disp)}`;
      // Poblar cifras dentro del bloque amarillo y mostrarlo
      $('cli-lc').textContent = fmt(lc);
      $('cli-disp').textContent = fmt(disp);
      exceedBox.style.display = 'flex';
      // Si es la primera vez que aparece tras este render, hacer scroll al
      // fondo del carrito para que el cliente lo vea sin tener que buscar.
      if(!wasShown){
        const cartScroll = document.querySelector('.cart-scroll');
        if(cartScroll){
          setTimeout(() => { cartScroll.scrollTop = cartScroll.scrollHeight; }, 50);
        }
      }
    }
  } else {
    $('total-msg').textContent = '';
    exceedBox.style.display = 'none';
  }
}

// ===== Validación RFC =====
const PEDIDO_MIN = 7000;
function validarRfc(){
  const inp = $('cli-rfc');
  const v = (inp.value || '').toUpperCase().trim();
  if(v !== inp.value) inp.value = v;

  // Caso 1: cliente no validado todavía
  if(!state.cliente){
    inp.classList.remove('error','success');
    setMsg('rfc-msg', '', '');
    return false;
  }

  // Caso 2: RFC vacío
  if(!v){
    inp.classList.remove('error','success');
    setMsg('rfc-msg', state.cliente._comodin
      ? 'Captura el RFC del cliente.'
      : 'Captura el RFC del cliente para validar.', '');
    return false;
  }

  // Caso 3: formato inválido
  const formatoOk = /^[A-ZÑ&]{3,4}\d{6}[A-Z\d]{3}$/.test(v);
  if(!formatoOk){
    inp.classList.add('error');
    inp.classList.remove('success');
    setMsg('rfc-msg', 'Formato de RFC inválido.', 'error');
    return false;
  }

  // Caso 4: cliente comodín — solo se valida formato
  if(state.cliente._comodin){
    inp.classList.remove('error');
    inp.classList.add('success');
    setMsg('rfc-msg', 'RFC válido.', 'success');
    return true;
  }

  // Caso 5: cliente normal — debe coincidir con el RFC del catálogo
  const rfcCatalogo = (state.cliente.rfc || '').toUpperCase().trim();
  if(!rfcCatalogo){
    // Cliente no tiene RFC en catálogo: aceptar el capturado con formato válido
    inp.classList.remove('error');
    inp.classList.add('success');
    setMsg('rfc-msg', 'RFC válido (cliente sin RFC registrado).', 'success');
    return true;
  }
  if(v !== rfcCatalogo){
    inp.classList.add('error');
    inp.classList.remove('success');
    setMsg('rfc-msg', 'El RFC no coincide con el registrado para este cliente.', 'error');
    return false;
  }

  // Todo OK
  inp.classList.remove('error');
  inp.classList.add('success');
  setMsg('rfc-msg', 'RFC verificado ✓', 'success');
  return true;
}

// ===== Validar y habilitar finalizar =====
function actualizarFinalizar(){
  const items = Object.values(state.carrito);
  const tieneCli = !!state.cliente;
  const email = $('cli-email').value.trim();
  const tel = $('cli-tel').value.replace(/\D/g,'');
  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const telOk = tel.length === 10;
  const rfcOk = validarRfc();
  // Total con IVA
  const total = items.reduce((s, it) => {
    if(!tienePrecio(it.p)) return s;
    return s + it.q * getPrecioPaquete(it.p) * 1.16;
  }, 0);
  const minOk = total >= PEDIDO_MIN;
  const ok = tieneCli && emailOk && telOk && rfcOk && items.length > 0 && minOk;
  $('btn-finalize').disabled = !ok;
  updateIdentityCardState(rfcOk);
}

// ===== Identity card: colapsar a chip cuando cliente + RFC verificados =====
function updateIdentityCardState(rfcOk){
  const card = document.getElementById('identity-card');
  if(!card) return;
  if(rfcOk === undefined) rfcOk = $('cli-rfc').classList.contains('success');
  const verified = !!state.cliente && rfcOk;
  card.classList.toggle('compact', verified);
  if(verified){
    const c = state.cliente;
    const num = c._comodin ? 'XXXXX' : c.n;
    const name = c._comodin ? 'Cliente comodín' : (c.nc || c.rs || '—');
    const lista = c.pl || 'Lista';
    $('chip-num').textContent = num;
    $('chip-name').textContent = name;
    $('chip-lista').textContent = lista;
  }
}

// ===== Filtros UI =====
function buildFilterUI(){
  // Grupos
  const grpSel = $('filter-grupo');
  grpSel.innerHTML = '<option value="">Grupo de temporada o productos</option>' +
    GRUPOS.map(g => `<option value="${g.n}">${g.n} (${g.q})</option>`).join('');
  grpSel.addEventListener('change', e => {
    state.filterGrupo = e.target.value;
    renderProductos();
  });

  // Página: input numérico (rango calculado desde páginas con productos)
  const paginas = new Set();
  PRODUCTS.forEach(p => p.p && paginas.add(p.p));
  const pagSorted = [...paginas].sort((a,b)=>a-b);
  const pagInput = $('filter-page');
  const pagClear = $('filter-page-clear');
  if(pagSorted.length){
    pagInput.min = pagSorted[0];
    pagInput.max = pagSorted[pagSorted.length-1];
    pagInput.placeholder = `${pagSorted[0]}-${pagSorted[pagSorted.length-1]}`;
  }
  function applyPagInput(){
    const v = pagInput.value.trim();
    const n = parseInt(v, 10);
    if(v === '' || isNaN(n)){
      state.filterPage = '';
      pagClear.style.display = 'none';
      pagInput.style.color = '';
    } else if(!paginas.has(n)){
      state.filterPage = String(n); // produce 0 resultados → empty state
      pagClear.style.display = 'inline';
      pagInput.style.color = 'var(--pad-red)';
    } else {
      state.filterPage = String(n);
      pagClear.style.display = 'inline';
      pagInput.style.color = '';
    }
    renderProductos();
  }
  pagInput.addEventListener('input', applyPagInput);
  pagInput.addEventListener('change', applyPagInput);
  pagClear.addEventListener('click', () => {
    pagInput.value = '';
    applyPagInput();
    pagInput.focus();
  });

  // Chips
  $('chip-especial').addEventListener('click', () => {
    state.filterEspecial = !state.filterEspecial;
    $('chip-especial').classList.toggle('active', state.filterEspecial);
    renderProductos();
  });
  $('chip-nuevos').addEventListener('click', () => {
    state.filterNuevos = !state.filterNuevos;
    $('chip-nuevos').classList.toggle('active', state.filterNuevos);
    renderProductos();
  });

  // Reset
  $('reset-filters').addEventListener('click', () => {
    state.filterEspecial = false;
    state.filterNuevos = false;
    state.filterGrupo = '';
    state.filterPage = '';
    state.search = '';
    $('search-input').value = '';
    $('search-clear').style.display = 'none';
    document.querySelectorAll('.filter-chip.active').forEach(c => c.classList.remove('active'));
    grpSel.value = '';
    pagInput.value = '';
    $('filter-page-clear').style.display = 'none';
    renderProductos();
  });

  // Cargar más
  $('btn-load-more').addEventListener('click', () => {
    state.showLimit += 60;
    renderProductos();
  });

  // Conteos
  const espCount = PRODUCTS.filter(p => p.e).length;
  $('qty-especial').textContent = espCount;
  const nuevosCount = PRODUCTS.filter(p => p.n).length;
  $('qty-nuevos').textContent = nuevosCount;
}

// ===== Búsqueda =====
let searchTimer;
function setupSearch(){
  $('search-input').addEventListener('input', e => {
    const v = e.target.value;
    $('search-clear').style.display = v ? 'inline-flex' : 'none';
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      state.search = v;
      state.showLimit = 60;
      renderProductos();
    }, 180);
  });
  $('search-clear').addEventListener('click', () => {
    $('search-input').value = '';
    $('search-clear').style.display = 'none';
    state.search = '';
    renderProductos();
  });
}

// ===== Cliente form =====
function setupClienteForm(){
  let cliTimer;
  $('cli-num').addEventListener('input', e => {
    clearTimeout(cliTimer);
    cliTimer = setTimeout(() => validarCliente(e.target.value), 350);
  });
  $('cli-num').addEventListener('blur', e => validarCliente(e.target.value));
  $('cli-email').addEventListener('input', actualizarFinalizar);
  $('cli-rfc').addEventListener('input', e => {
    // Forzar mayúsculas, quitar espacios
    let v = e.target.value.toUpperCase().replace(/\s/g,'');
    e.target.value = v;
    const eraValido = state._rfcValido === true;
    actualizarFinalizar();
    // Si el estado válido/inválido del RFC cambió, re-renderizar productos
    const esValido = clienteListo();
    if(eraValido !== esValido){
      state._rfcValido = esValido;
      renderProductos();
    }
  });
  $('cli-tel').addEventListener('input', e => {
    // Máscara (XX) XXXX-XXXX
    let d = e.target.value.replace(/\D/g,'').slice(0,10);
    let f = '';
    if(d.length > 0){ f = '('+d.slice(0,2); }
    if(d.length >= 2){ f += ') '; }
    if(d.length >= 2){ f += d.slice(2,6); }
    if(d.length >= 6){ f += '-'+d.slice(6,10); }
    e.target.value = f;
    actualizarFinalizar();
  });
  // Chip "editar": expandir identity-card y dar foco al campo de número de cliente
  const chipEdit = document.getElementById('chip-edit');
  if(chipEdit){
    chipEdit.addEventListener('click', () => {
      const card = document.getElementById('identity-card');
      if(card) card.classList.remove('compact');
      const cliNum = document.getElementById('cli-num');
      if(cliNum) cliNum.focus();
    });
  }
  bloquearForm(true);
}

// ===== Finalizar pedido =====
function setupFinalizar(){
  $('btn-finalize').addEventListener('click', generarPedido);
  $('btn-credit').addEventListener('click', abrirSolicitudCredito);
}
function generarPedido(){
  const items = Object.values(state.carrito);
  if(!state.cliente || items.length === 0) return;

  const cli = state.cliente;
  const numCli = cli._comodin ? 'XXXXX' : cli.n;
  const today = new Date();
  const ddmmyy = String(today.getDate()).padStart(2,'0') +
                 String(today.getMonth()+1).padStart(2,'0') +
                 String(today.getFullYear()).slice(-2);
  const filename = `${numCli}-${ddmmyy}.xlsx`;

  // Agrupar por GrupoPedido
  const porGrupo = {};
  items.forEach(it => {
    const g = it.p.g || 'OTROS';
    if(!porGrupo[g]) porGrupo[g] = [];
    porGrupo[g].push(it);
  });

  // Crear workbook con SheetJS
  const wb = XLSX.utils.book_new();

  // ===== Hoja 1: RESUMEN (siempre primera, con formato profesional) =====
  const subtotalSinIVA = items.reduce((s, it) => {
    if(!tienePrecio(it.p)) return s;
    return s + it.q * getPrecioPaquete(it.p);
  }, 0);
  const totalConIVA = subtotalSinIVA * 1.16;
  const fechaPedido = today.toLocaleDateString('es-MX', {day:'2-digit', month:'2-digit', year:'numeric'}) +
                      ' ' + today.toLocaleTimeString('es-MX', {hour:'2-digit', minute:'2-digit'});
  const nombreCli = cli._comodin
    ? 'Cliente comodín'
    : (cli.rs || cli.nc || '');
  const rfcCli = cli._comodin
    ? ($('cli-rfc').value || '').toUpperCase()
    : (($('cli-rfc').value || cli.rfc || '').toUpperCase());
  const correoCli = ($('cli-email').value || '').trim();
  const celularCli = $('cli-tel').value || '';

  // Paleta Padcolor para estilos
  const C = {
    blue: '0A3D8F',
    blueLight: 'E8EFFF',
    text: '2A3140',
    textSoft: '6B7385',
    green: '2EA674',
    greenLight: 'E6F7F0',
    white: 'FFFFFF',
    border: 'D8DDE6',
    grey50: 'F8F9FB',
  };
  const thinBorder = {
    top: {style:'thin', color:{rgb:C.border}},
    bottom: {style:'thin', color:{rgb:C.border}},
    left: {style:'thin', color:{rgb:C.border}},
    right: {style:'thin', color:{rgb:C.border}},
  };
  // Estilos reutilizables
  const stTitulo = {
    font:{name:'Calibri', sz:18, bold:true, color:{rgb:C.white}},
    fill:{patternType:'solid', fgColor:{rgb:C.blue}},
    alignment:{horizontal:'center', vertical:'center'},
    border: thinBorder,
  };
  const stSubtitulo = {
    font:{name:'Calibri', sz:10, italic:true, color:{rgb:C.textSoft}},
    fill:{patternType:'solid', fgColor:{rgb:C.grey50}},
    alignment:{horizontal:'center', vertical:'center'},
    border: thinBorder,
  };
  const stSeccion = {
    font:{name:'Calibri', sz:11, bold:true, color:{rgb:C.blue}},
    fill:{patternType:'solid', fgColor:{rgb:C.blueLight}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stLabel = {
    font:{name:'Calibri', sz:10, bold:true, color:{rgb:C.text}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stValue = {
    font:{name:'Calibri', sz:10, color:{rgb:C.text}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stMoney = {
    font:{name:'Calibri', sz:10, color:{rgb:C.text}},
    alignment:{horizontal:'right', vertical:'center', indent:1},
    numFmt:'"$"#,##0.00;[Red]-"$"#,##0.00',
    border: thinBorder,
  };
  const stTotalLabel = {
    font:{name:'Calibri', sz:12, bold:true, color:{rgb:C.green}},
    fill:{patternType:'solid', fgColor:{rgb:C.greenLight}},
    alignment:{horizontal:'left', vertical:'center', indent:1},
    border: thinBorder,
  };
  const stTotalValue = {
    font:{name:'Calibri', sz:13, bold:true, color:{rgb:C.green}},
    fill:{patternType:'solid', fgColor:{rgb:C.greenLight}},
    alignment:{horizontal:'right', vertical:'center', indent:1},
    numFmt:'"$"#,##0.00;[Red]-"$"#,##0.00',
    border: thinBorder,
  };

  // Construir hoja celda por celda (con estilos)
  // Layout (1-indexed visualmente, 0-indexed para SheetJS):
  // r0 (1)  : Título (merge A:B)
  // r1 (2)  : Subtítulo (merge A:B)
  // r2 (3)  : (vacío - separador)
  // r3 (4)  : Sección "DATOS DEL CLIENTE" (merge)
  // r4-r6   : 3 filas de datos del cliente
  // r7 (8)  : (vacío)
  // r8 (9)  : Sección "DATOS DE CONTACTO" (merge)
  // r9-r11  : 3 filas de contacto
  // r12 (13): (vacío)
  // r13 (14): Sección "RESUMEN FINANCIERO" (merge)
  // r14     : Subtotal sin IVA
  // r15     : Total con IVA (16%) - destacado
  const wsResumen = {};
  const set = (addr, value, style) => {
    const cell = {v: value, t: typeof value === 'number' ? 'n' : 's'};
    if(style) cell.s = style;
    wsResumen[addr] = cell;
  };

  set('A1', 'RESUMEN DEL PRE-PEDIDO', stTitulo); set('B1', '', stTitulo);
  set('A2', 'Padcolor — Papel, Diseño y Color S.A. de C.V.', stSubtitulo); set('B2', '', stSubtitulo);

  set('A4', 'DATOS DEL CLIENTE', stSeccion); set('B4', '', stSeccion);
  set('A5', 'Número de cliente', stLabel);      set('B5', numCli, stValue);
  set('A6', 'Nombre del cliente', stLabel);     set('B6', nombreCli, stValue);
  set('A7', 'RFC', stLabel);                    set('B7', rfcCli, stValue);

  set('A9', 'DATOS DE CONTACTO', stSeccion);    set('B9', '', stSeccion);
  set('A10', 'Correo de contacto', stLabel);    set('B10', correoCli, stValue);
  set('A11', 'Celular de contacto', stLabel);   set('B11', celularCli, stValue);
  set('A12', 'Fecha del pedido', stLabel);      set('B12', fechaPedido, stValue);

  set('A14', 'RESUMEN FINANCIERO', stSeccion);  set('B14', '', stSeccion);
  set('A15', 'Subtotal sin IVA', stLabel);      set('B15', subtotalSinIVA, stMoney);
  set('A16', 'Total con IVA (16%)', stTotalLabel); set('B16', totalConIVA, stTotalValue);

  // Rango de la hoja
  wsResumen['!ref'] = 'A1:B16';
  // Merges para que los headers y secciones ocupen las dos columnas
  wsResumen['!merges'] = [
    {s:{r:0,c:0}, e:{r:0,c:1}},  // A1:B1 - Título
    {s:{r:1,c:0}, e:{r:1,c:1}},  // A2:B2 - Subtítulo
    {s:{r:3,c:0}, e:{r:3,c:1}},  // A4:B4 - Sección 1
    {s:{r:8,c:0}, e:{r:8,c:1}},  // A9:B9 - Sección 2
    {s:{r:13,c:0}, e:{r:13,c:1}},// A14:B14 - Sección 3
  ];
  // Anchos de columnas
  wsResumen['!cols'] = [{wch:26}, {wch:42}];
  // Alturas: título más alto, secciones medianas
  wsResumen['!rows'] = [
    {hpt:34},  // 1 título
    {hpt:18},  // 2 subtítulo
    {hpt:8},   // 3 separador
    {hpt:22},  // 4 sección
    {hpt:20},  // 5
    {hpt:20},  // 6
    {hpt:20},  // 7
    {hpt:8},   // 8 separador
    {hpt:22},  // 9 sección
    {hpt:20},  // 10
    {hpt:20},  // 11
    {hpt:20},  // 12
    {hpt:8},   // 13 separador
    {hpt:22},  // 14 sección
    {hpt:22},  // 15
    {hpt:28},  // 16 total destacado
  ];

  XLSX.utils.book_append_sheet(wb, wsResumen, 'Resumen');

  // ===== Hojas por grupo =====
  // Orden: TODA OCASIÓN, PRECIO ESPECIAL, ESCOLAR, etc.
  const orden = ['TODA OCASIÓN','PRECIO ESPECIAL','ESCOLAR','HOJA, CARTULINA Y PAPEL BOND','CAJA PIZZA','DESCONTINUADOS','OTROS'];
  const grupos = Object.keys(porGrupo).sort((a,b) => {
    const ia = orden.indexOf(a); const ib = orden.indexOf(b);
    return (ia===-1?99:ia) - (ib===-1?99:ib);
  });

  grupos.forEach(g => {
    // Ordenar de mayor a menor cantidad pedida (en piezas)
    const lista = [...porGrupo[g]].sort((a,b) => (b.q*b.p.m) - (a.q*a.p.m));
    const rows = [['Código','Descripción','Cantidad (piezas)']];
    lista.forEach(it => {
      const piezas = it.q * it.p.m;
      rows.push([it.p.c, it.p.d, piezas]);
    });
    const ws = XLSX.utils.aoa_to_sheet(rows);
    // Anchos sugeridos
    ws['!cols'] = [{wch:14},{wch:60},{wch:14}];
    // Limitar nombre de hoja a 31 chars (Excel limit)
    let sheetName = g.length > 31 ? g.substring(0,28)+'...' : g;
    sheetName = sheetName.replace(/[\[\]\*\?\/\\:]/g,'_');
    XLSX.utils.book_append_sheet(wb, ws, sheetName);
  });

  // Descargar
  XLSX.writeFile(wb, filename);

  // Mensaje
  const ag = state.agente;
  let mensaje;
  if(cli._comodin){
    mensaje = `Tu pre-pedido se descargó como <strong>${filename}</strong> en tu carpeta de Descargas.<br><br>
      Envíalo por correo a <strong>Asistente de Ventas</strong>: <a href="mailto:auxventas@padcolor.com">auxventas@padcolor.com</a>.`;
  } else {
    const waFmt = formatWhatsApp(ag.wa);
    mensaje = `Tu pre-pedido se descargó como <strong>${filename}</strong> en tu carpeta de Descargas.<br><br>
      Envíalo a <strong>${ag.nom}</strong> por correo a <a href="mailto:${ag.mail}">${ag.mail}</a>${waFmt ? ' o por WhatsApp a <strong>'+waFmt+'</strong>':''}.`;
  }
  showModal('Pre-pedido generado ✓', `<div style="line-height:1.6">${mensaje}</div>`);

  // Limpiar carrito
  state.carrito = {};
  renderCarrito();
  actualizarFinalizar();
  renderProductos();
}

