// Estados de la República Mexicana (para selects de dirección)
const ESTADOS_MX = [
  'Aguascalientes','Baja California','Baja California Sur','Campeche','Chiapas',
  'Chihuahua','Ciudad de México','Coahuila','Colima','Durango','Estado de México',
  'Guanajuato','Guerrero','Hidalgo','Jalisco','Michoacán','Morelos','Nayarit',
  'Nuevo León','Oaxaca','Puebla','Querétaro','Quintana Roo','San Luis Potosí',
  'Sinaloa','Sonora','Tabasco','Tamaulipas','Tlaxcala','Veracruz','Yucatán','Zacatecas'
];
function optionsEstados(selected){
  return '<option value="">— Selecciona —</option>' +
    ESTADOS_MX.map(e => `<option value="${e}"${e === selected ? ' selected' : ''}>${e}</option>`).join('');
}

function abrirSolicitudCredito(){
  if(!state.cliente || state.cliente._comodin) return;
  const cli = state.cliente;
  const total = creditoCalcularTotal();
  const disp = Math.max(0, (cli.lc||0) - (cli.sa||0));
  const nuevaLinea = (cli.lc||0) + total;

  const html = `
    <p>Tu pre-pedido excede el crédito disponible. Para continuar, completa esta solicitud.</p>

    <div class="credit-summary">
      <div class="cs-row"><span class="cs-label">Cliente</span><span class="cs-value">${cli.n}</span></div>
      <div class="cs-row"><span class="cs-label">Línea actual</span><span class="cs-value">${fmt(cli.lc)}</span></div>
      <div class="cs-row"><span class="cs-label">Crédito disponible</span><span class="cs-value">${fmt(disp)}</span></div>
      <div class="cs-row"><span class="cs-label">Total del pre-pedido</span><span class="cs-value">${fmt(total)}</span></div>
      <div class="cs-row" style="grid-column:1/-1"><span class="cs-label">Nueva línea solicitada</span><span class="cs-value highlight">${fmt(nuevaLinea)}</span></div>
    </div>

    <div class="credit-section-title">1. Datos del solicitante</div>
    <div class="credit-field">
      <label>Nombre completo de la persona moral o persona física <span class="req">*</span></label>
      <input type="text" class="credit-input" id="cred-razon-social" placeholder="Razón social o nombre completo">
    </div>
    <div class="credit-subtitle">Nombre del solicitante (firmante)</div>
    <div class="credit-grid-3">
