// ---- Helpers del módulo de crédito ----
function creditoCalcularTotal(){
  return Object.values(state.carrito).reduce((s, it) => {
    return s + (tienePrecio(it.p) ? it.q * getPrecioPaquete(it.p) * 1.16 : 0);
  }, 0);
}
function formatPhoneInput(value){
  const d = (value||'').replace(/\D/g,'').slice(0, 10);
  if(d.length === 0) return '';
  if(d.length <= 2) return '(' + d;
  if(d.length <= 6) return '(' + d.slice(0,2) + ') ' + d.slice(2);
  return '(' + d.slice(0,2) + ') ' + d.slice(2,6) + '-' + d.slice(6);
}
// Formato (XX) XXXX XXXX — con espacios, para el teléfono móvil del firmante
function formatPhoneSpaces(value){
  const d = (value||'').replace(/\D/g,'').slice(0, 10);
  if(d.length === 0) return '';
  if(d.length <= 2) return '(' + d;
  if(d.length <= 6) return '(' + d.slice(0,2) + ') ' + d.slice(2);
  return '(' + d.slice(0,2) + ') ' + d.slice(2,6) + ' ' + d.slice(6);
}
// Arma una dirección completa legible a partir de sus partes
function armarDireccion(p){
  let s = (p.calle || '').trim();
  if(p.numext) s += ` #${p.numext.trim()}`;
  if(p.numint && p.numint.trim()) s += ` Int. ${p.numint.trim()}`;
  if(p.colonia) s += `, Col. ${p.colonia.trim()}`;
  if(p.ciudad) s += `, ${p.ciudad.trim()}`;
  if(p.estado) s += `, ${p.estado.trim()}`;
  if(p.cp) s += `, C.P. ${p.cp.trim()}`;
  if(p.pais) s += `, ${p.pais.trim()}`;
  return s;
}
function generarFechaArchivoCredito(){
  const d = new Date();
  return `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
}
function descargarPDF(bytes, nombre){
  const blob = new Blob([bytes], {type: 'application/pdf'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = nombre;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

// ---- Generación del pagaré (siempre sin firmas: cliente lo imprime y firma) ----
async function generarYDescargarPagare(){
  try {
    const datos = recolectarDatosPagare();
    const pdfBytes = await generarPagarePDF(datos);
    descargarPDF(pdfBytes, `Pagare_${state.cliente.n}_${generarFechaArchivoCredito()}.pdf`);
    toast('Pagaré descargado', 'success');
  } catch(e){
    console.error(e);
    toast('Error al generar pagaré: ' + e.message, 'error');
  }
}

function recolectarDatosPagare(){
  const total = creditoCalcularTotal();
  const monto = (state.cliente.lc||0) + total;
  const fecha = new Date();
  const meses = ['enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const fechaExpStr = `${fecha.getDate()} de ${meses[fecha.getMonth()]} de ${fecha.getFullYear()}`;
  // Vencimiento: exactamente un año posterior a la fecha de la solicitud
  const venc = new Date(fecha.getFullYear() + 1, fecha.getMonth(), fecha.getDate());
  const fechaVencStr = `${venc.getDate()} de ${meses[venc.getMonth()]} de ${venc.getFullYear()}`;

  // Recolectar datos del formulario (pueden no existir si el modal no está abierto)
  const v = id => { const el = $(id); return el ? el.value.trim() : ''; };
  // La razón social / nombre de la persona moral o física proviene SIEMPRE del
  // campo capturado en la solicitud (no del catálogo de clientes).
  const razonSocial = v('cred-razon-social') || '__________________';
  const solNombreCompleto = [v('cred-sol-nombres'), v('cred-sol-paterno'), v('cred-sol-materno')]
    .filter(Boolean).join(' ');
  const domicilioSolicitante = armarDireccion({
    calle: v('cred-sol-calle'), numext: v('cred-sol-numext'), numint: v('cred-sol-numint'),
    colonia: v('cred-sol-colonia'), ciudad: v('cred-sol-ciudad'), estado: v('cred-sol-estado'),
    cp: v('cred-sol-cp'), pais: v('cred-sol-pais'),
  }) || state.cliente.dom || '(Domicilio no registrado)';
  const avalNombreCompleto = [v('cred-aval-nombres'), v('cred-aval-paterno'), v('cred-aval-materno')]
    .filter(Boolean).join(' ');
  const domicilioAval = armarDireccion({
    calle: v('cred-aval-calle'), numext: v('cred-aval-numext'), numint: v('cred-aval-numint'),
    colonia: v('cred-aval-colonia'), ciudad: v('cred-aval-ciudad'), estado: v('cred-aval-estado'),
    cp: v('cred-aval-cp'), pais: v('cred-aval-pais'),
  });

  return {
    lugarExpedicion: 'Zapopan, Jalisco',
    fechaExpedicion: fechaExpStr,
    beneficiario: 'Papel, Diseño y Color S.A. de C.V.',
    domicilioBeneficiario: 'Avenida del Tigre 2005, Col. Hogares de Nuevo México, Zapopan, Jalisco, C.P. 45138',
    // Para el cuerpo del pagaré: la persona moral/física es el deudor
    deudor: razonSocial,
    razonSocial,
    solNombreCompleto: solNombreCompleto || '__________________',
    domicilioDeudor: domicilioSolicitante,
    rfcDeudor: ($('cli-rfc').value || state.cliente.rfc || '').toUpperCase().trim(),
    monto,
    montoFmt: monto.toLocaleString('es-MX', {minimumFractionDigits: 2, maximumFractionDigits: 2}),
    montoLetra: numeroALetras(monto),
    fechaVencimiento: fechaVencStr,
    tasaMoratoria: '2',
    ciudadJurisdiccion: 'Zapopan, Jalisco',
    avalNombre: avalNombreCompleto || '__________________',
    avalDomicilio: domicilioAval || '__________________',
  };
}

async function generarPagarePDF(d){
  const { PDFDocument, StandardFonts, rgb } = PDFLib;
  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage([612, 792]);
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  // Encabezado (sin folio)
  page.drawText('PAGARÉ', {x: 270, y: 740, font: fontBold, size: 20});
  page.drawText(`Bueno por: $${d.montoFmt} M.N.`, {x: 360, y: 705, font: fontBold, size: 12});

  // Cuerpo
  const cuerpo = `En ${d.lugarExpedicion}, a ${d.fechaExpedicion}.

Por el presente pagaré, ${d.razonSocial}, con domicilio en ${d.domicilioDeudor} y RFC ${d.rfcDeudor}, me obligo incondicionalmente a pagar a la orden de ${d.beneficiario}, con domicilio en ${d.domicilioBeneficiario}, la cantidad de $${d.montoFmt} M.N. (${d.montoLetra}), en ${d.domicilioBeneficiario}, el día ${d.fechaVencimiento}.

Esta cantidad la recibí a mi entera satisfacción.

En caso de mora, este pagaré causará un interés moratorio de ${d.tasaMoratoria}% mensual sobre el monto adeudado, computado por días naturales, a partir del día siguiente al vencimiento y hasta el día de su pago total.

Para el caso de incumplimiento en el pago de este pagaré, el suscriptor se obliga a pagar gastos y costas de cobranza, incluyendo honorarios legales.

El presente documento es título ejecutivo conforme a la Ley General de Títulos y Operaciones de Crédito.

El deudor y el aval se someten expresamente a la jurisdicción de los tribunales de ${d.ciudadJurisdiccion}, renunciando a cualquier otro fuero que pudiera corresponderles por razón de su domicilio presente o futuro. El aval responde solidariamente como obligado principal.`;

  const lineas = wordWrap(cuerpo, font, 11, 512);
  let y = 660;
  for(const ln of lineas){
    page.drawText(ln, {x: 50, y, font, size: 11});
    y -= 16;
    if(y < 320) break;
  }

  // ---- Bloque de firmas ----
  // Dos columnas. Bajo "DEUDOR": razón social, RFC, dirección (con wrap),
  // nombre completo del solicitante. Bajo "AVAL": nombre completo, dirección.
  // Las líneas de firma van varios espacios debajo de estos datos.
  const colDeudorX = 55;
  const colAvalX = 320;
  const colWidth = 240;

  // Helper para escribir un bloque de datos y devolver la Y final
  const escribirBloque = (x, titulo, lineasDatos, yStart) => {
    let yy = yStart;
    page.drawText(titulo, {x, y: yy, font: fontBold, size: 11});
    yy -= 16;
    for(const item of lineasDatos){
      // cada item puede necesitar wrap
      const wrapped = wordWrap(item, font, 9, colWidth);
      for(const wl of wrapped){
        page.drawText(wl, {x, y: yy, font, size: 9});
        yy -= 12;
      }
    }
    return yy;
  };

  const datosDeudor = [
    d.razonSocial,
    `RFC: ${d.rfcDeudor}`,
    `Domicilio: ${d.domicilioDeudor}`,
    `representada por ${d.solNombreCompleto}`,
    `Apoderado Legal`,
  ];
  const datosAval = [
    d.avalNombre,
    `Domicilio: ${d.avalDomicilio}`,
  ];

  const bloqueYStart = 290;
  const yFinDeudor = escribirBloque(colDeudorX, 'DEUDOR', datosDeudor, bloqueYStart);
  const yFinAval = escribirBloque(colAvalX, 'AVAL', datosAval, bloqueYStart);

  // La línea de firma va algunos espacios debajo del bloque más largo de cada columna
  const yLineaDeudor = yFinDeudor - 28;
  const yLineaAval = yFinAval - 28;

  page.drawLine({start: {x: colDeudorX, y: yLineaDeudor}, end: {x: colDeudorX + 200, y: yLineaDeudor}, thickness: 0.5});
  page.drawText('Firma del Deudor', {x: colDeudorX + 50, y: yLineaDeudor - 14, font, size: 10});

  page.drawLine({start: {x: colAvalX, y: yLineaAval}, end: {x: colAvalX + 200, y: yLineaAval}, thickness: 0.5});
  page.drawText('Firma del Aval', {x: colAvalX + 55, y: yLineaAval - 14, font, size: 10});

  return await pdfDoc.save();
}

function wordWrap(text, font, size, maxWidth){
  const lineas = [];
  const parrafos = text.split('\n');
  for(const para of parrafos){
    if(!para.trim()){ lineas.push(''); continue; }
    const words = para.split(' ');
    let cur = '';
    for(const w of words){
      const test = cur ? cur + ' ' + w : w;
      const width = font.widthOfTextAtSize(test, size);
      if(width > maxWidth && cur){
        lineas.push(cur);
        cur = w;
      } else {
        cur = test;
      }
    }
    if(cur) lineas.push(cur);
  }
  return lineas;
}

// ---- Conversión número a letras (PESOS) ----
function numeroALetras(n){
  const entero = Math.floor(n);
  const cents = Math.round((n - entero) * 100);
  return `${enteroALetras(entero)} PESOS ${String(cents).padStart(2, '0')}/100 M.N.`;
}

function enteroALetras(n){
  if(n === 0) return 'CERO';
  const unidades = ['', 'UN', 'DOS', 'TRES', 'CUATRO', 'CINCO', 'SEIS', 'SIETE', 'OCHO', 'NUEVE'];
  const especiales = ['DIEZ', 'ONCE', 'DOCE', 'TRECE', 'CATORCE', 'QUINCE', 'DIECISÉIS', 'DIECISIETE', 'DIECIOCHO', 'DIECINUEVE'];
  const decenas = ['', '', 'VEINTI', 'TREINTA', 'CUARENTA', 'CINCUENTA', 'SESENTA', 'SETENTA', 'OCHENTA', 'NOVENTA'];
  const centenas = ['', 'CIENTO', 'DOSCIENTOS', 'TRESCIENTOS', 'CUATROCIENTOS', 'QUINIENTOS', 'SEISCIENTOS', 'SETECIENTOS', 'OCHOCIENTOS', 'NOVECIENTOS'];

  function leer3(x){
    if(x === 0) return '';
    if(x === 100) return 'CIEN';
    let r = '';
    const c = Math.floor(x / 100);
    const dy = x % 100;
    const dec = Math.floor(dy / 10);
    const u = dy % 10;
    if(c) r += centenas[c] + ' ';
    if(dy >= 10 && dy <= 19) r += especiales[dy - 10];
    else if(dec === 2) r += (u === 0 ? 'VEINTE' : 'VEINTI' + unidades[u]);
    else if(dec > 2){
      r += decenas[dec];
      if(u) r += ' Y ' + unidades[u];
    } else if(u) r += unidades[u];
    return r.trim();
  }

  let res = '';
  const millones = Math.floor(n / 1000000);
  const miles = Math.floor((n % 1000000) / 1000);
  const resto = n % 1000;
  if(millones){
    res += (millones === 1 ? 'UN MILLÓN' : leer3(millones) + ' MILLONES') + ' ';
  }
  if(miles){
    if(miles === 1) res += 'MIL ';
    else res += leer3(miles) + ' MIL ';
  }
  if(resto) res += leer3(resto);
  return res.trim().replace(/\s+/g, ' ');
}

// ---- Procesar solicitud (generar expediente consolidado) ----
async function procesarSolicitudCredito(){
  const errEl = $('cred-error');
  errEl.textContent = '';
  const v = id => { const el = $(id); return el ? el.value.trim() : ''; };

  // ----- Datos del solicitante -----
  const razonSocial = v('cred-razon-social');
  const solNombres = v('cred-sol-nombres');
  const solPaterno = v('cred-sol-paterno');
  const solEmail = v('cred-sol-email');
  const solTel = v('cred-sol-tel').replace(/\D/g, '');
  const solCalle = v('cred-sol-calle');
  const solNumext = v('cred-sol-numext');
  const solColonia = v('cred-sol-colonia');
  const solCiudad = v('cred-sol-ciudad');
  const solEstado = v('cred-sol-estado');
  const solCP = v('cred-sol-cp');
  const solPais = v('cred-sol-pais');

  if(!razonSocial){ errEl.textContent = 'Captura el nombre completo de la persona moral o física'; return; }
  if(!solNombres || !solPaterno){ errEl.textContent = 'Captura nombres y apellido paterno del solicitante'; return; }
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(solEmail)){ errEl.textContent = 'Captura un correo electrónico válido del firmante'; return; }
  if(solTel.length !== 10){ errEl.textContent = 'El teléfono móvil del firmante debe tener 10 dígitos'; return; }
  if(!solCalle || !solNumext || !solColonia || !solCiudad || !solEstado || !solCP || !solPais){
    errEl.textContent = 'Completa todos los campos de la dirección del solicitante (incluido el estado)';
    return;
  }

  // ----- Datos del aval -----
  const avalNombres = v('cred-aval-nombres');
  const avalPaterno = v('cred-aval-paterno');
  const avalCalle = v('cred-aval-calle');
  const avalNumext = v('cred-aval-numext');
  const avalColonia = v('cred-aval-colonia');
  const avalCiudad = v('cred-aval-ciudad');
  const avalEstado = v('cred-aval-estado');
  const avalCP = v('cred-aval-cp');
  const avalPais = v('cred-aval-pais');

  if(!avalNombres || !avalPaterno){ errEl.textContent = 'Captura nombres y apellido paterno del aval'; return; }
  if(!avalCalle || !avalNumext || !avalColonia || !avalCiudad || !avalEstado || !avalCP || !avalPais){
    errEl.textContent = 'Completa todos los campos de la dirección del aval (incluido el estado)';
    return;
  }

  // ----- Adjuntos requeridos -----
  const ineFr = $('cred-ine-frente').files[0];
  const ineRv = $('cred-ine-reverso').files[0];
  const compr = $('cred-comprobante').files[0];
  const avalIneFr = $('cred-aval-ine-frente').files[0];
  const avalIneRv = $('cred-aval-ine-reverso').files[0];

  if(!ineFr || !ineRv || !compr || !avalIneFr || !avalIneRv){
    errEl.textContent = 'Adjunta todas las imágenes requeridas (INE solicitante frente y reverso, comprobante de domicilio, INE aval frente y reverso)';
    return;
  }

  const pagareFirmadoFile = $('cred-pagare-firmado').files[0];
  if(!pagareFirmadoFile){
    errEl.textContent = 'Sube el pagaré firmado (foto o escaneo)';
    return;
  }

  // Nombres completos para la carátula
  const solNombreCompleto = [solNombres, solPaterno, v('cred-sol-materno')].filter(Boolean).join(' ');
  const avalNombreCompleto = [avalNombres, avalPaterno, v('cred-aval-materno')].filter(Boolean).join(' ');

  // Generar expediente consolidado
  const btn = $('btn-cred-submit');
  const txtOriginal = btn.textContent;
  btn.textContent = 'Generando…';
  btn.disabled = true;

  try {
    const componentes = [];

    // 1. Carátula
    componentes.push(await generarCaratulaPDF({
      razonSocial,
      solNombreCompleto,
      solEmail,
      solTel: formatPhoneSpaces(solTel),
      avalNombreCompleto,
    }));

    // 2. Adjuntos del solicitante
    componentes.push(await imageOrPdfToPdfBytes(ineFr, 'INE solicitante - frente'));
    componentes.push(await imageOrPdfToPdfBytes(ineRv, 'INE solicitante - reverso'));
    componentes.push(await imageOrPdfToPdfBytes(compr, 'Comprobante de domicilio'));

    // 3. Adjuntos del aval
    componentes.push(await imageOrPdfToPdfBytes(avalIneFr, 'INE aval - frente'));
    componentes.push(await imageOrPdfToPdfBytes(avalIneRv, 'INE aval - reverso'));

    // 4. Pagaré firmado físicamente (escaneado)
    componentes.push(await imageOrPdfToPdfBytes(pagareFirmadoFile, 'Pagaré firmado físicamente'));

    const final = await mergePDFs(componentes);
    const fname = `SolicitudCredito_${state.cliente.n}_${generarFechaArchivoCredito()}.pdf`;
    descargarPDF(final, fname);

    // Cerrar modal y mostrar mensaje de confirmación
    closeModal();
    const correoAg = (state.agente && state.agente.mail) ? state.agente.mail : '—';
    const msgFinal = `
      <p>✓ Tu solicitud se descargó como <strong>${fname}</strong>.</p>
      <div class="credit-highlight-box" style="margin-top:14px">
        Envíala por correo a <a href="mailto:adgomez@padcolor.com"><strong>adgomez@padcolor.com</strong></a>
        con copia a <a href="mailto:jlogistica@padcolor.com"><strong>jlogistica@padcolor.com</strong></a>
        y a tu ejecutivo de ventas: <a href="mailto:${correoAg}"><strong>${correoAg}</strong></a>.
      </div>
      <p style="margin-top:14px">Gracias por tu solicitud, con estos documentos tramitamos tu extensión de crédito. Te haremos llegar una guía para que mandes Pagaré en original.</p>
    `;
    setTimeout(() => showModal('✓ Solicitud generada', msgFinal), 200);

  } catch(e){
    console.error(e);
    errEl.textContent = 'Error al generar la solicitud: ' + e.message;
    btn.textContent = txtOriginal;
    btn.disabled = false;
  }
}

async function generarCaratulaPDF(info){
  const { PDFDocument, StandardFonts, rgb } = PDFLib;
  const doc = await PDFDocument.create();
  const page = doc.addPage([612, 792]);
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const fontBold = await doc.embedFont(StandardFonts.HelveticaBold);

  page.drawText('SOLICITUD DE AUMENTO', {x: 50, y: 740, font: fontBold, size: 22});
  page.drawText('DE LÍNEA DE CRÉDITO', {x: 50, y: 715, font: fontBold, size: 22});

  page.drawLine({start: {x: 50, y: 695}, end: {x: 562, y: 695}, thickness: 1, color: rgb(0.04, 0.24, 0.56)});

  let y = 670;
  const drawRow = (label, value) => {
    page.drawText(label, {x: 50, y, font: fontBold, size: 10, color: rgb(0.3, 0.3, 0.3)});
    const wrapped = wordWrap(String(value), font, 11, 330);
    for(let i = 0; i < wrapped.length; i++){
      page.drawText(wrapped[i], {x: 230, y, font, size: 11});
      if(i < wrapped.length - 1) y -= 14;
    }
    y -= 22;
  };

  drawRow('Fecha de solicitud:', new Date().toLocaleDateString('es-MX'));
  drawRow('Número de cliente:', state.cliente.n);
  drawRow('Persona moral/física:', info.razonSocial);
  drawRow('RFC:', ($('cli-rfc').value || state.cliente.rfc || '').toUpperCase());
  drawRow('Solicitante (firmante):', info.solNombreCompleto);
  drawRow('Correo del firmante:', info.solEmail);
  drawRow('Teléfono del firmante:', info.solTel);
  drawRow('Aval:', info.avalNombreCompleto);

  y -= 10;
  page.drawText('RESUMEN FINANCIERO', {x: 50, y, font: fontBold, size: 13});
  y -= 20;

  const total = creditoCalcularTotal();
  const lc = state.cliente.lc || 0;
  const sa = state.cliente.sa || 0;
  const disp = Math.max(0, lc - sa);
  drawRow('Línea de crédito actual:', '$' + lc.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Saldo actual:', '$' + sa.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Crédito disponible:', '$' + disp.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Total del pre-pedido:', '$' + total.toLocaleString('es-MX', {minimumFractionDigits: 2}));
  drawRow('Nueva línea solicitada:', '$' + (lc + total).toLocaleString('es-MX', {minimumFractionDigits: 2}));

  y -= 10;
  page.drawText('PRODUCTOS DEL PRE-PEDIDO', {x: 50, y, font: fontBold, size: 13});
  y -= 18;

  page.drawText('Código', {x: 50, y, font: fontBold, size: 9});
  page.drawText('Descripción', {x: 160, y, font: fontBold, size: 9});
  page.drawText('Cant.', {x: 480, y, font: fontBold, size: 9});
  page.drawText('Subtotal', {x: 525, y, font: fontBold, size: 9});
  y -= 14;

  Object.values(state.carrito).forEach(({p, q}) => {
    if(y < 80) return;
    if(!tienePrecio(p)) return;
    const precioPq = getPrecioPaquete(p);
    const sub = q * precioPq * 1.16;
    page.drawText(p.c, {x: 50, y, font, size: 8});
    page.drawText((p.d||'').substring(0, 50), {x: 160, y, font, size: 8});
    page.drawText(String(q), {x: 480, y, font, size: 8});
    page.drawText('$' + sub.toLocaleString('es-MX', {minimumFractionDigits: 2}), {x: 525, y, font, size: 8});
    y -= 12;
  });

  return await doc.save();
}

async function imageOrPdfToPdfBytes(file, titulo){
  const { PDFDocument, StandardFonts, rgb } = PDFLib;
  const buf = await file.arrayBuffer();

  // Si ya es PDF, devolverlo tal cual
  if(file.type === 'application/pdf' || /\.pdf$/i.test(file.name)){
    return new Uint8Array(buf);
  }

  // Imagen → embeber en una página
  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.HelveticaBold);

  let img;
  if(file.type === 'image/png' || /\.png$/i.test(file.name)){
    img = await doc.embedPng(buf);
  } else {
    img = await doc.embedJpg(buf);
  }

  const page = doc.addPage([612, 792]);
  page.drawText(titulo, {x: 50, y: 750, font, size: 14, color: rgb(0.04, 0.24, 0.56)});

  // Escalar manteniendo proporción
  const maxW = 512, maxH = 660;
  const scale = Math.min(maxW / img.width, maxH / img.height, 1);
  const w = img.width * scale;
  const h = img.height * scale;
  const x = (612 - w) / 2;
  const y = 50 + (660 - h) / 2;
  page.drawImage(img, {x, y, width: w, height: h});

  return await doc.save();
}

async function mergePDFs(arrayBuffers){
  const { PDFDocument } = PDFLib;
  const final = await PDFDocument.create();
  for(const buf of arrayBuffers){
    const doc = await PDFDocument.load(buf);
    const pages = await final.copyPages(doc, doc.getPageIndices());
    pages.forEach(p => final.addPage(p));
  }
  return await final.save();
}

// ===== Init =====
function init(){
  buildFilterUI();
  setupSearch();
  setupClienteForm();
  setupFinalizar();
  renderProductos();
  renderCarrito();
}

// API global para handlers inline en carrito
window.__padcolor = {
  cartQty: cambiarQtyCarrito,
  cartRemove: eliminarDelCarrito,
};

// Esperar DOM listo
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

})();
</script>

